customers = input.required<Customer[]>();

// Auswahl springt auf das erste Element, sobald sich die Liste ändert,
// kann aber vom Benutzer überschrieben werden
selected = linkedSignal(() => this.customers()[0]);

onPick(c: Customer) {
  this.selected.set(c);
}

// Ersetzt das Muster "ein effect setzt ein Signal anhand eines anderen zurück"

constructor() {
  // Filtertext im Browser sichern, sobald er sich ändert
  effect(() => {
    localStorage.setItem('customerFilter', this.filterText());
  });

  // Aufräumen mit onCleanup, bevor der effect erneut läuft oder zerstört wird
  effect((onCleanup) => {
    const id = setInterval(() => this.refresh(), this.pollMs());
    onCleanup(() => clearInterval(id));
  });
}
// untracked(() => ...): Lesen ohne Abhängigkeit
// Ein effect muss im Injection Context entstehen (Konstruktor, Feldinitialisierer)

list = signal<Customer[]>([]);

this.list().push(c);                 // Falsch: Signal merkt nichts
this.list.update(l => [...l, c]);    // Richtig: neue Referenz

// Eintrag ändern, ebenfalls mit neuer Referenz
this.list.update(l => l.map(x => x.id === c.id ? { ...x, ...changes } : x));

// Signals vergleichen mit ===: gleiches Array bedeutet "keine Änderung"
