// Falsch: der erste effect schreibt in b, der zweite liest b und schreibt in a ...
effect(() => this.b.set(this.a() * 2));
effect(() => this.a.set(this.b() + 1));   // Endlosschleife, schwer nachzuvollziehen

// Besser: eine Quelle und ein computed
a = signal(1);
b = computed(() => this.a() * 2);

// Schreiben auf Signals in einem computed ist verboten (Fehler NG0600)

